INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Binding of Isaac: Rebirth', 'The Binding of Isaac: Rebirth is a top down, procedurally-generated roguelike game, remade based on the original game The Binding of Isaac. You play as Isaac, a little boy who is chased to the basement by his mother who intends to kill Isaac for her savior. You explore different levels, collect items and try to defeat your mother.. and whatever other evil awaits you. If you die, you restart with none of your items you collected, and you must explore the basement and beyond again.' FROM games WHERE igdb_id = 7789 ON CONFLICT (game_id, language_code) DO NOTHING;
