INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bullet Soul Infinite Burst', 'Bullet Soul Infinite Burst is a vertically scrolling shooting game crossing old-school gameplay with a bullet hell twist. It adds numerous gameplay enhancements over its predecessor, Bullet Soul, not least of which is Burst Mode. The same aggressive, bullet-cancelling gameplay, now with more destruction, more coins and more tunes. Shooting fans, it''s time to welcome back the true Japanese shooting experience!' FROM games WHERE igdb_id = 5645 ON CONFLICT (game_id, language_code) DO NOTHING;
