INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pro Cycling Manager 2014', 'Pro Cycling Manager 2014 will thrill fans of sports management, catapulting them to the head of one of the 75 pro teams in a riveting cycling season where you take part in over 200 competitions and 550 stages! This extensive 2014 edition offers meticulously rendered graphics, new off-race management options (R&D, financial management and improved sponsor relations, etc.), a more dynamic transfer market, a more realistic injury system, a brand new and highly intuitive interface and a race gameplay that is full of great features, including consecutive orders and race tactics!' FROM games WHERE igdb_id = 8251 ON CONFLICT (game_id, language_code) DO NOTHING;
