INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deception IV: Blood Ties', 'Deception IV: Blood Ties follows the story of Laegrinna, an animated fragment of an imprisoned Devil''s soul, as she battles her enemies by mischievously luring them into strategically placed traps. From rolling boulders and spiked walls to spring boards, iron maidens, human cannons, falling bathtubs and banana peels, the player can choose from a multitude of dramatic, sadistic, and comical traps in order to finish off an enemy.
