INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mx-vs-atv-supercross', 24306, '2014-10-28', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co25te.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ongveykjfrjlsn7nkwxu.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MX vs. ATV: Supercross', 'Marking the revival of the best-selling MX vs. ATV racing series, MX vs. ATV Supercross is centered around the high-flying, mud-churning Supercross sport. Rip, jump and scrub your way on a variety of tracks and try to cross the finish line first against more than 40 official riders to attain all that motocross glory. Choose between bikes or ATVs, multiple game modes including Career, Single races, and online multiplayer events with up to 12 players. Perform amazing tricks to impress your fans or just "whip" over jumps to finish the race first. Customize your rider with items from numerous licensed motocross companies to kick up dirt and dust on your way to victory.' FROM games WHERE igdb_id = 24306 ON CONFLICT (game_id, language_code) DO NOTHING;
