INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Broken Age: The Complete Adventure', 'Broken Age is a point-and-click adventure telling the stories of a young boy and girl leading parallel lives. Vella Tartine has been chosen by her village to be sacrificed to a terrible monster — but she decides to fight back. Meanwhile, Shay Volta is living a solitary life on a spaceship under the care of a motherly computer, but he wants to break free to lead adventures and do good in the world. Adventures ensue.' FROM games WHERE igdb_id = 20865 ON CONFLICT (game_id, language_code) DO NOTHING;
