INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gary Grigsby''s War in the West', 'Based on the War in the East engine with years of additional major features and improvements, Gary Grigsby’s War in the West 1943-45 is the most ambitious and detailed computer wargame on the Western Front of World War II ever made. Starting with the Summer 1943 invasions of Sicily and Italy and proceeding through the invasions of France and the drive into Germany, War in the West brings you all the Allied campaigns in Western Europe and the capability to re-fight the Western Front according to your plan.' FROM games WHERE igdb_id = 59528 ON CONFLICT (game_id, language_code) DO NOTHING;
