INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Table Top Racing', 'Table Top Racing Free is the multi-award winning, combat-racer brought to you by the co-creator of Sony''s blockbuster PlayStation franchise ''WipEout''. With console-quality graphics and intensifying gameplay, it offers countless hours of fun and a real challenge for players of all skill levels. ''Table Top Racing'' pits all manner of crazy vehicles, battling each other in a world of table-top race tracks and over-sized obstacles. Upgrade your cars in the garage, master both pickup weapons and wheel weapons and explore the circuit limits and discover secret shortcuts!' FROM games WHERE igdb_id = 8350 ON CONFLICT (game_id, language_code) DO NOTHING;
