INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Mega Baseball', 'Super Mega Baseball is a video game developed by independent studio Metalhead Software in Victoria, BC, Canada. It was first released on December 16, 2014 as a PlayStation 3 and PlayStation 4 cross-buy title on the US PlayStation Store. It was released on the European PlayStation Store on April 1, 2015. An updated version called Super Mega Baseball: Extra Innings was released on Xbox One on August 14, 2015 and it was released on Steam for PC on August 21, 2015. The extra features from this version will be released as free DLC for the PlayStation 3 and PlayStation 4 in 2015.' FROM games WHERE igdb_id = 22152 ON CONFLICT (game_id, language_code) DO NOTHING;
