INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'J-Stars Victory Vs', 'Your favorite Shonen Jump heroes jump off the page and duke it out on your screen in J-Stars Victory VS, a 2v2 brawler that features an insane roster filled with manga & anime stars. J-Stars Victory Vs+ invites fans and gamers to play with their favorite manga/anime characters and progress in the JUMP World through different environments recalling Naruto, Dragon Ball Z, One Piece and other memorable moments for every manga and anime fan.' FROM games WHERE igdb_id = 7355 ON CONFLICT (game_id, language_code) DO NOTHING;
