INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '4PM', '4PM is a short, narrative driven game, made by one person as an attempt to tell a real, thriller story in the form of an interactive experience. It has high production values and a cinematic style. It is, with your support, a first in a series of smaller, narrative driven experiences, that spare no expense on audio-visual style.' FROM games WHERE igdb_id = 8115 ON CONFLICT (game_id, language_code) DO NOTHING;
