INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Invizimals: The Lost Kingdom', 'Explore the world of the Invizimals as the smash hit series comes to PlayStation 3 in a thrilling third-person adventure. You are Hiro, a young explorer who discovers a magical portal that teleports you to the Lost Kingdom -- a land under attack from a cruel, rampaging robot army. Transform into 16 of the most popular Invizimals, using their unique powers and abilities to solve puzzles and battle against your enemies.
