INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jet Gunner', 'Jet Gunner is a 2D platform action indie game that''s full of Nestalgia. Full of action, gunfights, bosses and explosions so if you''re into the whole 8-Bit vibe you should love this. From the sound, to the graphics to the flicker, this should pay tribute to those classic hard as nails, run ''n'' gun games. Hopefully this should wet your appetite for re-living the good ol'' days.' FROM games WHERE igdb_id = 17655 ON CONFLICT (game_id, language_code) DO NOTHING;
