INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Re;Lord 1: The Witch of Herfort and Stuffed Animals', 'In a fantasy world where magic exists, the demon realm faced an unprecedented danger. Three "witches of disaster" appeared and invaded the demon country of Saarland. Due to the recent peaceful times, Saarland lacked the skills to protect the territory of Groesen.' FROM games WHERE igdb_id = 90256 ON CONFLICT (game_id, language_code) DO NOTHING;
