INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('senran-kagura-2-deep-crimson', 11079, '2014-08-07', 65, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9k2d.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3nnk.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Senran Kagura 2: Deep Crimson', 'Senran Kagura 2: Deep Crimson is a 3D side-scrolling action game made for the 3DS, and was developed by the same team which created Senran Kagura Burst. New gameplay is included in the form of pair battles, which allows a second character, to which the player can give commands, to fight alongside the player''s character. The playable characters in the game are customizable. Outfits, accessory size and position, and hair color can be changed to the player''s liking. Augmented reality functionality was also included in the game. The playable characters could be posed against a real-life background in a variety of poses.' FROM games WHERE igdb_id = 11079 ON CONFLICT (game_id, language_code) DO NOTHING;
