INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hatsune-miku-project-diva-f-2nd', 9626, '2014-03-06', 79, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3wew.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/zdop5ysruqn5qsciz80x.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hatsune Miku: Project Diva F 2nd', 'Hatsune Miku: Project DIVA F 2nd is a rhythm game, and is the direct sequel to Hatsune Miku: Project DIVA F. The game is set to have a similar play style to its predecessor whilst featuring new songs, returning songs from previous games, and character modules. New in-game mechanisms original to the game include sliding touchscreen notes, and double scratch notes. The DIVA room also features various minigames that can be played, including a clapping game. Another new addition to Project DIVA F 2nd over the previous game is the ability to change skins for the rhythm game mode, where decorative skin designs can be downloaded as DLC. The game features cross-save support between PS Vita and PS3 systems.' FROM games WHERE igdb_id = 9626 ON CONFLICT (game_id, language_code) DO NOTHING;
