INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Secrets of Rætikon', 'Secrets of Rætikon is an action-focussed exploration game with an open world. Fly through the savage mountains of the Alps and collect parts of ancient machines. The world is rich in interactivity. Trees, rocks, plants and animals – everything is physics based and can be grabbed and dragged around.' FROM games WHERE igdb_id = 8276 ON CONFLICT (game_id, language_code) DO NOTHING;
