INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moebius: Empire Rising', 'The first in an all-new series of paranormal mystery adventures from award-winning game designer Jane Jensen, creator of the bestselling Gabriel Knight series and Gray Matter. Step into the shoes of Malachi Rector, a brilliant antiques dealer and historian whose photographic memory and eye for deduction transforms locations and clues into interactive puzzle pieces and historical patterns. Players will criss-cross the globe''s most exotic locales as they solve challenging riddles, search for hidden clues, and connect evidence and events to uncover a global conspiracy that threatens to bring worldwide ruin. When a young woman is brutally slain and a secret government agency decides to investigate, only Malachi Rector holds the key to unlocking this puzzle—a man whose destiny may not be his own to define.' FROM games WHERE igdb_id = 5540 ON CONFLICT (game_id, language_code) DO NOTHING;
