INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Infectonator: Survivors', '"Infectonator : Survivors" is a Randomized Permadeath Survival Simulator that combines RTS, Tower Defense, Roguelike, and Management-Simulation gameplay. The goal is to lead a group of survivors in a struggle to stay alive and find rescue in a zombie apocalyptic world. You must scavenge resources, build defenses, and find a way to survive in a game where death is permanent and levels are randomly generated.' FROM games WHERE igdb_id = 16914 ON CONFLICT (game_id, language_code) DO NOTHING;
