INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Farm Frenzy 4', 'Save grandpa and grandma''s farm from foreclosure in the wacky and wonderful Farm Frenzy 4! The Farm Frenzy series of casual sims gets a makeover in this ALL NEW sequel. Choose and dress your character, and then get busy saving the family farm! Buy and care for a variety of animals, collect the goods they produce and then manufacture products for sale in town, keeping a close eye on your bank account and the clock to make sure you balance your resources well. Perform challenging tasks for colorful characters, protect your farm from bears and moles, and earn a trophy on each of the game''s 90 levels to unlock dozens of achievements!' FROM games WHERE igdb_id = 17317 ON CONFLICT (game_id, language_code) DO NOTHING;
