INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('atelier-shallie-alchemists-of-the-dusk-sea', 11513, '2014-06-26', 77, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2s37.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/p4ihwjunts3dkbs7vzdw.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Atelier Shallie: Alchemists of the Dusk Sea', 'Atelier Shallie: Alchemists of the Dusk Sea is a Japanese role-playing video game developed by Gust. As part of the "Atelier" series of games, it is the third and final installment of the "Dusk" storyline. The game''s story takes place about 10 years after the beginning of Atelier Ayesha: The Alchemist of Dusk and 6 years after the beginning of Atelier Escha & Logy: Alchemists of the Dusk Sky. The player is able to choose to play as one of two characters, each with a differing storyline and adventure; regardless of which character is chosen, the flow of the game remains the same. In comparison to previous Atelier games, fields are significantly larger, and the player is able to harvest a wider variety of items and raw materials to use for mixing.' FROM games WHERE igdb_id = 11513 ON CONFLICT (game_id, language_code) DO NOTHING;
