INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Costume Quest 2', 'In developer Double Fine’s triumphant return to Auburn Pines, our candy-crazed crusaders Wren and Reynold must once again protect Halloween from untold horrors, and grown-ups! Your favorite trick-or-treaters will come armed with a new batch of costumes they wear to transform into giant super powered fantasy Hallowarriors. Fans of the original can look forward to a sweet upgraded battle system and a story that is unmistakably Double Fine.' FROM games WHERE igdb_id = 5638 ON CONFLICT (game_id, language_code) DO NOTHING;
