INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Styx: Master of Shadows', 'Styx: Master of Shadows is an infiltration game with RPG elements taking place in a dark fantasy universe, where you sneak, steal and assassinate your way through as Styx, a Goblin two-centuries of age. Deep inside the vertiginous and multi-layered forsaken Tower of Akenash, where Humans and Elves protect the World-Tree, source of the Amber – a powerful and magical golden sap – is hidden Styx’ chance to understand his true origin... and to make a fortune at the same time.' FROM games WHERE igdb_id = 6072 ON CONFLICT (game_id, language_code) DO NOTHING;
