INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SuperPower 2: Steam Edition', 'SuperPower 2 is the only global geopolitical simulation game which allows players to control entire countries. Players control countries in 3 major areas: political, economic and military, but this time, in a beautiful real-time 3D environment. Players build up their own countries and increase their influence in the broader world while competing against sophisticated A.I. Along the way, gamers make use of economic sanctions, political alliances, and military actions to wage their battles.' FROM games WHERE igdb_id = 90586 ON CONFLICT (game_id, language_code) DO NOTHING;
