INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeon of the Endless', 'In Dungeon of the Endless, the player takes the role of the survivors of a prison spaceship, its escape pod having crashed to the surface of a strange planet. To escape, they must take an energy crystal through several floors, each floor filled with a number of dangerous creatures. To help, the player can have their survivors explore the randomly generated levels to collect resources as to enable power to various rooms and construct turrets to fend off the enemies when they move the crystal from its starting point to the elevator to the next floor.' FROM games WHERE igdb_id = 9683 ON CONFLICT (game_id, language_code) DO NOTHING;
