INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cannon Brawl', 'Cannon Brawl is a 2D action strategy game with big explosions and destructible terrain. Command the action from your airship to build cannons, capture mines, expand your territory and more. Choose from a multitude of buildings, cannons and towers to assemble a force that will rain destruction from the sky and defeat your enemy! Advance your military campaign across the map in single player mode, or duke it out in multiplayer mode.' FROM games WHERE igdb_id = 13675 ON CONFLICT (game_id, language_code) DO NOTHING;
