INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soulcalibur: Lost Swords', 'Soulcalibur: Lost Swords was a free-to-play fighting game distributed through PlayStation Network. The game is based on Soulcalibur V and uses the same weapon-based fighting system from previous games; however, several of the gameplay mechanics are altered, simplified or otherwise removed. Similar to other free-to-play titles like Tekken Revolution, microtransactions are offered, some of which remove the playtime limit of the game. The game is also periodically updated with new content, including new events, items, and characters.' FROM games WHERE igdb_id = 22030 ON CONFLICT (game_id, language_code) DO NOTHING;
