INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'aerofly RC 7', 'Learn to fly radio controlled (R/C) models with aerofly RC 7. When it comes to learning and improving R/C flying skills, aerofly RC 7 is the number one choice for R/C pilots. Our state of the art physics simulation gives you a stunning level of realism. Together with our superb model details and awesome scenery quality you will feel as if standing on a real flying field.' FROM games WHERE igdb_id = 17839 ON CONFLICT (game_id, language_code) DO NOTHING;
