INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elite: Dangerous', 'The next game in the Elite series - an amazing space epic with stunning visuals, incredible gameplay, breath-taking scope and award-winning sound. All content can be enjoyed in game any mode: solo, personal invite-only group or open/MMO. Carve your own path through the richest, largest gaming sandbox ever created, a 1:1 scale representation of the Milky Way galaxy, set against a backdrop of raw anarchy, galactic powerplays and political intrigue.' FROM games WHERE igdb_id = 2955 ON CONFLICT (game_id, language_code) DO NOTHING;
