INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tokyo Twilight Ghost Hunters', 'Tokyo Twilight Ghost Hunters is a Japanese adventure game that includes adventure game and visual novel gameplay, as well as strategy role-playing elements. The visual novel half will cover chatting with other students and teachers, with a unique art style that has the illustrated characters constantly moving and shifting. Instead of conversation trees, however, players will adjust the flow of conversation by combining one of five emotions and one of the five senses.' FROM games WHERE igdb_id = 12195 ON CONFLICT (game_id, language_code) DO NOTHING;
