INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('soccer-stars', 38059, '2014-05-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6ynp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1prk.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soccer Stars', 'It’s the last minute of the game and your opponent has the ball… but he’s lost it! What a chance to score the winner… you take aim, shoot… GOOOOOOAAAAAALLLLL! With simple gameplay and great physics, Soccer Stars is easy to pick up and fun to play! In true competitive style, challenge your opponents all over the world for online table soccer matches! Compete in different tiers, from different countries! Play online against people from all over the world or against your friends! Login with your Facebook account and challenge your friends to show them what it means to be a Soccer Legend and take the cup home! Oh, and you can also play offline against a friend in the same device! You can also customize your Soccer Stars experience by collecting the different teams! Show off your style and defend your nation’s colors! What are you waiting for? Everyone else is already playing Soccer Stars! Don’t miss out on this chance to have tons of fun! KEY FEATURES: - Online and offline multiplayer game - Simple and fun gameplay - Amazing ball physics - Online tournaments against players from all over the world - Play against your friends - Collect different teams and cups' FROM games WHERE igdb_id = 38059 ON CONFLICT (game_id, language_code) DO NOTHING;
