INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('claire', 10082, '2014-07-07', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3wf9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1ctm.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Claire', 'Claire is alone, lost, and hunted. The world has quickly becomes shrouded in darkness with unseen threats stalking Claire from the shadows. Aided by her dog and armed only with a flashlight, Claire must conquer her fear and find her comatose mother. However, there are others lost in the darkness seeking salvation. Claire must decide who she is going to save. With every choice she''ll begin to discover who she really is and whether she deserves to be saved herself.' FROM games WHERE igdb_id = 10082 ON CONFLICT (game_id, language_code) DO NOTHING;
