INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TxK', 'From the acclaimed designer of Tempest 2000 comes the system-shocking shooter TxK. The game draws on the spirit of the classic T2K, extending and enhancing it using the fantastic graphical power of the PS Vita system. TxK brings players new terrains, new bonus rounds, new enemies and weapons, all blazing on your screen with color and light in a graphics display designed to fit the sensory-overload gameplay, and backed by original music by an array of musicians.' FROM games WHERE igdb_id = 10061 ON CONFLICT (game_id, language_code) DO NOTHING;
