INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World of Tanks: Blitz', 'World of Tanks Blitz is truly World of Tanks on-the-go. It has the great visuals and satisfying controls, both built from the ground up to feel natural on the platform. And it has the same great tank-battle gameplay that World of Tanks has been known for. Furthermore, we intend to keep Blitz updated regularly with free content updates that give everyone access to new vehicles, maps, and game modes.' FROM games WHERE igdb_id = 7393 ON CONFLICT (game_id, language_code) DO NOTHING;
