INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dengeki Bunko: Fighting Climax', 'Dengeki Bunko: Fighting Climax is a 2D arcade fighting game developed to celebrate the 20th anniversary of ASCII Media Works'' Dengeki Bunko imprint, featuring various characters from light novels published under the imprint. The game was initially launched in Japanese arcades and was later ported to home consoles.' FROM games WHERE igdb_id = 11448 ON CONFLICT (game_id, language_code) DO NOTHING;
