INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wayward Manor', 'Wayward Manor invites you to jump into the afterlife of a disgruntled ghost, trying to reclaim his house from its newfound owners. Set in the 1920s, this puzzle, adventure game transports players to an era of dark screwball comedy where they must unlock the secrets of a twisted mansion. Players will discover the quirks of Wayward Manor''s unwelcome guests and choose how to prey on their darkest fears.' FROM games WHERE igdb_id = 16624 ON CONFLICT (game_id, language_code) DO NOTHING;
