INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney Infinity 2.0: Marvel Super Heroes', 'In Disney Infinity: Marvel Super Heroes, players will use real-world interactive Marvel figures to activate original storylines (Play Sets) in the virtual game worlds of some of Marvels most popular franchises, including The Avengers. In the Play Sets - penned by award-winning Marvel comic writer Brian Michael Bendis - players will be able to take on the role of more than 20 Marvel characters including Captain America, Iron Man, Black Widow, Thor, Hulk and Hawkeye to battle enemies, complete challenging missions, solve puzzles and ultimately save the world from destruction.' FROM games WHERE igdb_id = 17818 ON CONFLICT (game_id, language_code) DO NOTHING;
