INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO Batman 3: Beyond Gotham', 'LEGO Batman 3: Beyond Gotham is an action-adventure game developed by TT Games and released in 2014. The game features Batman and other DC Comics characters traveling beyond Earth to stop the villain Brainiac. Players explore various locations, solve puzzles, and engage in combat while collecting LEGO studs and unlocking characters. The game includes a large roster of DC heroes and villains, each with unique abilities.' FROM games WHERE igdb_id = 7685 ON CONFLICT (game_id, language_code) DO NOTHING;
