INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadowrun: Dragonfall - Director''s Cut', 'Shadowrun: Dragonfall - Director’s Cut is a standalone release of Harebrained Schemes'' critically-acclaimed Dragonfall campaign, which first premiered as a major expansion for Shadowrun Returns. The Director''s Cut adds a host of new content and enhancements to the original game: 5 all-new missions, alternate endings, new music, a redesigned interface, team customization options, a revamped combat system, and more - making it the definitive version of this one-of-a-kind cyberpunk RPG experience.' FROM games WHERE igdb_id = 8864 ON CONFLICT (game_id, language_code) DO NOTHING;
