INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bombing Bastards', 'Have a blast! Bomb oodles of nasty critters in a series of 30 wicked mazes! Defeat hellish bosses in heroic fights! Play solo or with friends, offline or online, in merciless battles! Embark on a hilarious journey with the witty Dr. Wallow to conquer the galaxy in this explosively fun arcade game!' FROM games WHERE igdb_id = 17653 ON CONFLICT (game_id, language_code) DO NOTHING;
