INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chronicles of a Dark Lord: Episode 2 War of the Abyss', 'Chronicles of a Dark Lord: Episode 2 War of The Abyss is the next episode in the epic JRPG series Chronicles of a Dark Lord. Experience the 30+ hour long continuation of the saga of the Dark Lord, Magus Drakhen Lee, in this innovative next installment that will draw you into the world of Cora like never before with immersive, all new high-resolution artwork and lush landscapes.' FROM games WHERE igdb_id = 7856 ON CONFLICT (game_id, language_code) DO NOTHING;
