INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('flashpoint-campaigns-red-storm-players-edition', 36202, '2014-11-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2q63.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ardk9.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flashpoint Campaigns: Red Storm - Player''s Edition', 'You are the commander of either NATO or Soviet forces locked in battle on the ground in 1980’s Central Europe. As commander, it is your task to provide the battle plan orders to your units. You need to know your mission objectives, strength and weakness of both your forces and you enemy, lay of the land, weather, and time of day in order to come out on the winning end. Your crews will do their best to follow your orders and execute the plan, but in war, no plan survives first contact. You will need to think on the fly and adjust to the ever changing flow of battle. 
