INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harvest Moon: The Lost Valley', 'In Harvest Moon 3D: The Lost Valley, players will experience the role-playing farm simulation in a three-dimensional setting for the first time. The game has a fully customizable world, and players can customize their field in any way they see fit: from a field full of tulips to a valley filled with water, the choice is up to you. You''ve never played a Harvest Moon game quite like this!' FROM games WHERE igdb_id = 7419 ON CONFLICT (game_id, language_code) DO NOTHING;
