INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fable-anniversary', 7658, '2014-02-04', 65, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co22lr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7mj.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fable Anniversary', 'Fully re-mastered with HD visuals and audio, Fable Anniversary is a stunning rendition of the original game that will delight faithful fans and new players alike! The all new Heroic difficulty setting will test the mettle of even the most hardcore Fable fan. With no Resurrection Phials and even more lethal enemies to contend with, will you be able to survive? Forge a hero based on your actions: age and evolve a hero or villain through the actions you choose and the path you follow-be it for good, evil, or in-between. Build your living legend: Through deeds and actions, build a name for yourself across the land. Recruit allies and followers. Gain glory or notoriety. Who will you be? With an entirely new lighting system, slick new interface, all new textures, models and gameplay, Fable Anniversary is the full HD, definitive Fable experience.' FROM games WHERE igdb_id = 7658 ON CONFLICT (game_id, language_code) DO NOTHING;
