INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Last Tinker: City of Colors', 'The Last Tinker is a joyous action adventure and definitely no platformer, as there is no jump button. Koru, a boy from the slums of Colortown, must rise and stand against the Bleakness, a dark force intent on wiping out joy. Koru must use color and emotion to restore life to Colortown!' FROM games WHERE igdb_id = 2346 ON CONFLICT (game_id, language_code) DO NOTHING;
