INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ascendant', 'Ascendant is the unforgiving beat ''em up that challenges you with a new world each time you play. It utilizes a number of modern roguelike elements such as permadeath and procedurally generated environments. You are a demigod who invades a plane controlled by your rivals. They will stop at nothing to eliminate you. Only the most impressive warriors will triumph over their armies of zealots and beasts.' FROM games WHERE igdb_id = 9222 ON CONFLICT (game_id, language_code) DO NOTHING;
