INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Last Inua', 'A father and son tale, Last Inua will leave you breathless with its immersive, emotional and captivating gameplay. Last Inua is an immersive and emotional, award winning 2D platform adventure game developed by Glowforth. Designed for the young and old and mixing classic platform genres, culminating in a captivating experience, Last Inua tells the tale of an Inuit family’s fight for survival against a fearsome demon and the harsh elements of the mythical Arctic.' FROM games WHERE igdb_id = 10494 ON CONFLICT (game_id, language_code) DO NOTHING;
