INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yo-Kai Watch 2: Psychic Specters', 'Become inspirited and complete the ultimate Yo-Kai Watch experience. The strange but friendly troublemakers, Yo-kai, are back in a time-traveling adventure, and this time their mysterious world is packed with exclusive quests, wicked Yo-kai to befriend, fully new areas to explore, and a revamped Blasters action co-op mode featuring new bosses.' FROM games WHERE igdb_id = 27129 ON CONFLICT (game_id, language_code) DO NOTHING;
