INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Watch Dogs', 'Set in Chicago, where a central network of computers connects everyone and everything, Watch Dogs explores the impact of technology within our society. Using the city as your weapon, you will embark on a personal mission to inflict your own brand of justice. Chicago''s overarching network is known as the Central Operating System (ctOS), and it controls almost all of the city''s technology and information - including key data on all of the city''s residents.' FROM games WHERE igdb_id = 1121 ON CONFLICT (game_id, language_code) DO NOTHING;
