INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('goat-simulator', 5335, '2014-04-01', 52, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2dhr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar75a.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Goat Simulator', 'Goat Simulator is a third-person perspective game in which the player controls a goat. There does not appear to be any kind of storyline or plot. The player is free to explore the game''s world as a goat, destroying things in the environment, running, jumping, and licking. "Goat Simulator is like an old school skating game, except instead of being a skater, you''re a goat, and instead of doing tricks, you wreck stuff," explained the game''s creators.' FROM games WHERE igdb_id = 5335 ON CONFLICT (game_id, language_code) DO NOTHING;
