INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'IL-2 Sturmovik: Battle of Stalingrad', 'IL-2 Sturmovik: Battle of Stalingrad is the continuation of the legendary IL-2 Sturmovik series that has set the standard for combat flight games for more than 10 years. This new entry into the series will offer virtual pilots an even more accurate simulation of the legendary air battles of World War II. A new higher level of physics modeling, damage modeling and aerodynamics has been achieved which allows for far greater realism than in any other title.' FROM games WHERE igdb_id = 17995 ON CONFLICT (game_id, language_code) DO NOTHING;
