INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Taxi!', 'Combining elements of arcade simulation and strategic management, Taxi! puts you in control of an up and coming cab firm based in any one of three 3D cities. You''ll begin with a rundown old taxi, picking up passengers and fulfilling a variety of dispatch missions until you manage to muster up enough cash to upgrade your cab and invest in new vehicles.' FROM games WHERE igdb_id = 9454 ON CONFLICT (game_id, language_code) DO NOTHING;
