INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BlazBlue: Chrono Phantasma Extend', 'BlazBlue: Chrono Phantasma Extend (formerly dubbed as BlazBlue: Chrono Phantasma 2.0 in Arcade version) is a 2D fighting game and the enhanced version of BlazBlue: Chrono Phantasma. Chrono Phantasma Extend adds two additional characters: Lambda-11 and Celica A. Mercury. The console release introduced extra story modes, such as the beach scenario from the Playstation Vita version of Chrono Phantasma, a new story based on the BlazBlue: Remix Heart manga, and additional scenarios for certain characters such as Kokonoe, Kagura, and Bullet. For the localized version of Extend, Library Mode reintroduced from the Japanese release. The Playstation Vita version of Chrono Phantasma Extend also adds dual audio to the Story Mode, which was not present in the original Vita release.' FROM games WHERE igdb_id = 11612 ON CONFLICT (game_id, language_code) DO NOTHING;
