INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nba-live-15', 7717, '2014-10-28', 66, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2bz4.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NBA Live 15', 'NBA Live 15 arrives with 500+ core gameplay improvements to deliver a truly fluid, exciting and authentic basketball gaming experience. Reimagined visuals drop you courtside alongside the game’s biggest stars. See the intensity on a player’s face as he nails a game-winner, or the frustration of a heart-wrenching loss. All-new real-time physics on dunks and layups replicate some of the NBA’s most amazing physical plays, letting you posterize your opponent or deny his attempt at the rim. Add into the mix always-connected online game modes and LIVE’s Synergy Sports partnership and you’ll never miss a beat during the NBA season with new content updated daily, all season long.' FROM games WHERE igdb_id = 7717 ON CONFLICT (game_id, language_code) DO NOTHING;
