INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Strike Vector', 'Strike Vector is a Brutal aerial FPS that will see you test your skills online against other players in the tradition of Quake 3 and Unreal Tournament. The game offers an hardcore learning curve for those who don''t fear to die a lot at first but who will get a massive rewarding feeling when they will master the game and dominate the battlefield.' FROM games WHERE igdb_id = 9464 ON CONFLICT (game_id, language_code) DO NOTHING;
