INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('titanfall', 2115, '2014-03-11', 84, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3wo1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/gh2l7ezwl6qdrt6zc9kb.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Titanfall', 'In Titanfall, players fight on a war-torn planet in six-on-six online multiplayer-only matches as mech-style Titans and their pilots. The game''s action is fast-paced: as pilots, players can run along walls and link jumps together parkour-style, use a variety of futuristic military weapons, and employ one of three special abilities: cloaking, stimming (increasing speed and health regeneration) and radar pinging; as Titans, players are equipped with more destructive armaments and special protective shields, with no limit to their abilities besides cooldown and reloading.' FROM games WHERE igdb_id = 2115 ON CONFLICT (game_id, language_code) DO NOTHING;
