INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('metal-gear-solid-v-ground-zeroes', 5328, '2014-03-18', 79, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1v88.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1cga.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metal Gear Solid V: Ground Zeroes', 'Metal Gear Solid V: Ground Zeroes is a prologue to Metal Gear Solid V: The Phantom Pain. It offers players new sneaking and traversal methods compared to its predecessors, as well as the choice in what order the story events take place by selecting missions by advance. The most important change for this title is the shift to an open world design with a real-time day and night cycle doing away with the linear mission approach of previous games. The game was originally developed as a mission for The Phantom Pain, but an extended development time resulted in director Hideo Kojima splitting the specific portion of the game as a stand-alone product so that players could get early access to Metal Gear Solid V.' FROM games WHERE igdb_id = 5328 ON CONFLICT (game_id, language_code) DO NOTHING;
