INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Noir Syndrome', 'Noir Syndrome is a procedurally generated Detective Murder-Mystery with a new story every time! Featuring slick pixel art animations and a jazzy soundtrack, the player is thrown right in to a highly stylized vision of film noir. Visit locations, interrogate suspects, search for clues, and eventually solve the case before the killer escapes - or you wind up dead yourself.' FROM games WHERE igdb_id = 17380 ON CONFLICT (game_id, language_code) DO NOTHING;
