INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Infamous: Second Son', 'Infamous: Second Son, a PlayStation 4 exclusive , brings you an action adventure game where surrounded by a society that fears them, superhumans are ruthlessly hunted down and caged by the Department of Unified Protection. Step into a locked-down Seattle as Delsin Rowe, who has recently discovered his superhuman power and is now capable of fighting back against the oppressive DUP. Enjoy your power as you choose how you will push your awesome abilities to the limit and witness the consequences of your actions as they affect the city and people around you.' FROM games WHERE igdb_id = 1941 ON CONFLICT (game_id, language_code) DO NOTHING;
