INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeon Defenders Eternity', 'Dungeon Defenders Eternity is the definitive version of the hit tower defense action RPG! Slice, shoot and pulverize your enemies, or build defenses to do the dirty work for you. Grab three friends and build a team of heroes from twelve different classes, each with their own defenses and abilities. Then embark on an adventure to defend Etheria from the Old Ones’ army!' FROM games WHERE igdb_id = 17417 ON CONFLICT (game_id, language_code) DO NOTHING;
