INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pandora: First Contact', 'The ancient Messari return to Pandora with all their might, deploying portals and terrifying ion storms. From these portals come forces never before seen by mankind, and an infestation spreads across Pandora. The strongest factions are the ones that have to fear them most, but they will spare no one.About the GamePandora: First Contact is a science fiction 4X turn-based strategy game on a planetary scale.' FROM games WHERE igdb_id = 17185 ON CONFLICT (game_id, language_code) DO NOTHING;
