INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Transistor', 'An unconventional tactical action RPG in which after a powerful group called the Camerata cause measureless destruction through the ambiguous settlement of Cloudbank, Red, a famous singer in the city, goes on a journey along with her lover who is trapped inside the Transistor, a powerful machine with mysterious properties, to get to the bottom of the situation and get her lost voice back.' FROM games WHERE igdb_id = 3022 ON CONFLICT (game_id, language_code) DO NOTHING;
