INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lovely Planet', 'With boots of speed on your feet, an infinite supply of bullets for your semi-automatic and the ability to jump over twice your own height, you''re well equipped to go up against any enemy on your quest to reach Lovely Planet! Balance between jumping around dodging bullets and taking aim for a better shot at your enemies, don''t waste time camping at cover spots and waiting for enemies to pop out - artfully evade the onslaught of bullets and defeat all baddies that stand in your way!' FROM games WHERE igdb_id = 14326 ON CONFLICT (game_id, language_code) DO NOTHING;
