INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Last of Us Remastered', 'The Last of Us Remastered is an updated release of the PS3 game The Last of Us. It is identical to the PS3 version but runs at a 1080p resolution and incorporates character models with a higher resolution. There are also improved shadows and lighting, upgraded textures, 60 frames per second and other types of improvements. In addition to the base game, two map packs and the expansion The Last of Us: Left Behind are included.' FROM games WHERE igdb_id = 6036 ON CONFLICT (game_id, language_code) DO NOTHING;
