INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'School of Dragons: How to Train Your Dragon', 'School of Dragons was a MMORPG based on DreamWorks Animation’s How to Train Your Dragon franchise. Players raised and trained their own dragon, interact with characters from the HTTYD franchise, join clans and embark upon journeys and quests alongside their Viking pals in-game. School of Dragons was the ultimate HTTYD experience for any fan and gamer. On June 30th The Game Closed it''s Doors.' FROM games WHERE igdb_id = 36191 ON CONFLICT (game_id, language_code) DO NOTHING;
