INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sandmason', 'You are a mine worker, stuck deep in an underground cave system. All you have is your hi-tech mining tools. In order to get out of the caves you have to shape the dynamic environment to your advantage. You can also create force fields for different purposes. Roast enemies with the laser field or jump higher with the bouncy field, for example.' FROM games WHERE igdb_id = 17278 ON CONFLICT (game_id, language_code) DO NOTHING;
