INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Transformers: Rise of the Dark Spark', 'Transformers: Rise of the Dark Spark is a third-person action game that connects the movie and Cybertron universes through a quest to secure the powerful Dark Spark artifact. Players control over 40 Transformers characters, freely switching between robot and vehicle forms while battling across Earth and Cybertron. The game features a shared progression system between its single-player campaign and four-player cooperative Escalation mode, where players unlock upgrades and rewards that carry over between both experiences.' FROM games WHERE igdb_id = 16583 ON CONFLICT (game_id, language_code) DO NOTHING;
