INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Smite', 'Smite is the online battleground of the gods. Players choose from a diverse cast of deities and use their unique powers to triumph over the opposition in 5v5 team matches. Smite is a new take on the MOBA genre; rather than observing from above the action, the game’s third person perspective puts players into the thick of combat. Instead of clicking the mouse to move, players use the familiar WASD keys to move and fight their way through Smite’s dynamic battlegrounds.' FROM games WHERE igdb_id = 5607 ON CONFLICT (game_id, language_code) DO NOTHING;
