INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marvel Spider-Man Unlimited', 'Spider-Man Unlimited is an endless runner video game developed and published by Gameloft; it is based on the Marvel Comics superhero Spider-Man. The player controls the title character and his alternate versions during his fight against the members of the Sinister Six and their multiverse counterparts. The game''s main mode features definitive goals in contrast to the traditional aim of running as far as possible. The game is also known for having regular, special, time-limited, community events.' FROM games WHERE igdb_id = 89103 ON CONFLICT (game_id, language_code) DO NOTHING;
