INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dreamfall Chapters', 'Dreamfall Chapters is an episodic, story-driven adventure game about choices and consequences, dreams and reality, magic and science, chaos and order, and the broken heroes whose actions will shape the course of history in all worlds. With a brand new storyline, Dreamfall Chapters introduces new players to The Longest Journey Saga, while returning players will get the conclusion they have been waiting for ever since the end of Dreamfall: The Longest Journey.' FROM games WHERE igdb_id = 1962 ON CONFLICT (game_id, language_code) DO NOTHING;
