INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sonic-boom-shattered-crystal', 7855, '2014-11-11', 47, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7be4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1i2d.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic Boom: Shattered Crystal', 'In Sonic Boom: Shattered Crystal, Amy discovers a secret ancient language and manuscript detailing the history and whereabouts of a Lost Crystal of Power. The evil and vile villain, Lyric the Last Ancient, kidnaps Amy in his eagerness to get his claws on this long-forgotten power that has been hidden throughout the jungles and canyons of a mysterious new island. Sonic must team up with Tails, Knuckles and new friend Sticks the Badger to trace Amy’s footsteps and save her from the clutches of Lyric and his robot army. By trusting in their own abilities and working as a team, they will prove they are stronger together than they are apart.' FROM games WHERE igdb_id = 7855 ON CONFLICT (game_id, language_code) DO NOTHING;
