INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Castle Doctrine', 'The Castle Doctrine is a massively-multiplayer game of burglary and home defense. It''s 1991, and things are bad. You''re a guy with a house and family. Other players are coming to take what''s yours. Build security to stop them. Study their houses, buy tools, and break in to take what''s theirs. Everything you do is permanent' FROM games WHERE igdb_id = 16651 ON CONFLICT (game_id, language_code) DO NOTHING;
