INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NEStalgia', 'NEStalgia is an original multiplayer RPG inspired by the glory days of traditional console RPGs. Essentially "Dragon Warrior 3 meets World of Warcraft", NEStalgia is an amalgam of the best generations of RPG gaming. Players wage classic turn based battles in multiplayer parties while enjoying modern trappings such as a full-featured quest system. Those who prefer to go solo can recruit almost any monster in the game to fight alongside them as they explore every nook and cranny of NEStalgia''s expansive 8-bit world.' FROM games WHERE igdb_id = 16650 ON CONFLICT (game_id, language_code) DO NOTHING;
