INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magicite', 'Explore, craft, and survive in this Multiplayer RPG Platformer with permanent death! Featuring many Rogue-like elements, Magicite randomly generates each underground dungeon for you and your friends to delve deep into. Chop trees, mine ores, and hunt beasts in order to collect the resources and materials you need to survive the harsh and unforgiving environment. With a ton of character traits, stats, companions, and classes, players will have a different experience each play through! Be prepared to die... A LOT.' FROM games WHERE igdb_id = 7883 ON CONFLICT (game_id, language_code) DO NOTHING;
