INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heavy Bullets', 'Armed with a simple yet stylish revolver and six devastatingly plump bullets, you must reset the security mainframe to restore order and reap the rewards of a job well done. To succeed in the game, players will need to move carefully and make smart use of their bullets, items, and the environment as rushing into new areas is the fastest way to get killed in the untamed wild of the neon corridors.' FROM games WHERE igdb_id = 10402 ON CONFLICT (game_id, language_code) DO NOTHING;
