INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sportsfriends', 'Sportsfriends is a collection of four local multiplayer games designed for social play. The package includes BaraBariBall, a competitive fighting game with sports elements; Super Pole Riders, a physics-based pole vaulting duel; Hokra, a fast-paced sports game; and Johann Sebastian Joust, a physical party game that uses motion controllers. Each game focuses on face-to-face competition and social interaction.' FROM games WHERE igdb_id = 9865 ON CONFLICT (game_id, language_code) DO NOTHING;
