INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hitman Go', 'Hitman GO is a turn-based puzzle game with beautifully rendered diorama-style set pieces. You will strategically navigate fixed spaces on a grid to avoid enemies and take out your target or infiltrate well-guarded locations. You really have to think about each move and all the Hitman tools of the trade you would expect are included; disguises, distractions, sniper rifles and even 47’s iconic Silverballers.' FROM games WHERE igdb_id = 6073 ON CONFLICT (game_id, language_code) DO NOTHING;
