INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Motorsport Manager', 'Have you got what it takes to become the manager of a high-performance motorsport team? Motorsport Manager is a highly detailed, best-in-class management game for fans of motorsport. You’ll hire the drivers, build the cars and embed yourself in the dynamic world of racing.' FROM games WHERE igdb_id = 19293 ON CONFLICT (game_id, language_code) DO NOTHING;
