INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guise of the Wolf', 'The game is a first person Gothic action adventure game set in the medieval kingdom of Uhorsko. You play Dominik, a young alchemist summoned to protect the kingdom from a ravenous beast. Dominik''s goals soon change as he discovers he has been bitten, and cursed to become the very thing he has set out to stop.' FROM games WHERE igdb_id = 7669 ON CONFLICT (game_id, language_code) DO NOTHING;
