INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Time Force Ultra', 'Super Time Force Ultra is an action-packed platformer with a time-travelling twist! You’re in control of time itself, bending and stretching it to your advantage on the battlefield. Rewind time and choose when to jump back into the action, teaming-up with your past selves in a unique single-player co-op experience! Take control of up to 16 unique characters, and battle across 6 different time periods, from the long-ago past to the far-away future.' FROM games WHERE igdb_id = 8879 ON CONFLICT (game_id, language_code) DO NOTHING;
