INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('influent-language-learning-game', 17037, '2014-03-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2jly.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arrxs.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Influent Language Learning Game', 'Inspired by Dreamcast titles of old (namely Shenmue and Toy Commander) Influent immerses players in a fully interactive 3D environment where the names for absolutely every object in the game can be gleaned with a single click! In fact, even more information can be learned with a double-click! Every door, drawer, and cabinet can be opened with a right-click here and a right-click there, revealing more and more things to be learned! Packed to the brim with hundreds of native audio pronunciations (painstakingly recorded specifically for this game), Influent offers players a unique opportunity to enjoy learning both vocabulary and pronunciation in the language of their choice.
