INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultimate General: Gettysburg', 'Ultimate General: Gettysburg is a Tactical Battle Simulator that allows you to lead thousands of soldiers in the famous Battle of Gettysburg as commander of either the Union or Confederate army. The game features the most accurately created map, complex morale, innovative control mechanics and smart AI. You have the freedom to use different strategies while the battle progresses. Your decisions and military performance play a crucial role in the result. Lead your army and win the Battle of Gettysburg!' FROM games WHERE igdb_id = 8424 ON CONFLICT (game_id, language_code) DO NOTHING;
