INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Death Skid Marks', 'Death Skid Marks is an ultra-violent top down car combat game where you will kill countless numbers of foes in the most noble quest of all: getting to a kickass music concert. Fight groupies, rednecks, neo-nazis, religious fanatics, the police, robots, aliens, suicide bombers and your own self-destructive urges to play Russian roulette. Upgrade your car with parts and your crew with illicit substances, buy weapons and special items, fight using guns, melee and your driving skills. Travel 666 KMs along route 666 and face increasingly impossible odds. Unlock tons of content such as cars and bumper stickers.' FROM games WHERE igdb_id = 17897 ON CONFLICT (game_id, language_code) DO NOTHING;
