INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '2048', 'Created by Italian web developer Gabriele Cirulli, 2048 is a single-player sliding tile puzzle video game that challenges players to combine numbered tiles on a 4x4 grid to create a tile with the number 2048. Originally written in JavaScript and CSS over a weekend, it was released in March 2014 as free and open-source software.' FROM games WHERE igdb_id = 9105 ON CONFLICT (game_id, language_code) DO NOTHING;
