INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('road-not-taken', 8510, '2014-08-05', 65, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co25ey.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1ctk.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Road Not Taken', 'Road Not Taken is a roguelike puzzle game about surviving life''s surprises. You play as a ranger adventuring through a vast, unforgiving forest in the aftermath of a brutal winter storm, rescuing children who have lost their way. Randomly generated levels deliver a limitless supply of possibilities to explore and challenges to overcome. Your actions will influence not only your own story, but that of the villagers you hope to befriend and the town you call home.' FROM games WHERE igdb_id = 8510 ON CONFLICT (game_id, language_code) DO NOTHING;
