INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-floor-is-jelly', 11309, '2014-05-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2cr7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/whcwptqngpgnawgoodm4.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Floor is Jelly', 'Who hasn''t dreamt, at some point, of filling a pool full of jello and swimming in it? In some of us, that dream never died. Some of us kept dreaming: what if the whole street was jello? Or the continent? The world!? The Floor is Jelly posits a universe made of jello, made purely for one''s own amusement. No longer need we look to our walls and our floors and sigh, "How solid! How sadly immalleable! How I wish for a world consisting only of Non-Newtonian fluids!" That world has arrived, via the dark magic of videogames, as The Floor is Jelly.' FROM games WHERE igdb_id = 11309 ON CONFLICT (game_id, language_code) DO NOTHING;
