INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sproggiwood', 'Bring civilization to Sproggiwood, a story-driven, turn-based roguelike set in a humorous world inspired by Finnish mythology. One moment, you''re a simple farmer tending your grove -- the next, you’re lured through a mysterious portal by a talking sheep. Now you’re the prisoner of Sproggi, a mischievous forest spirit who tasks you with taming the monsters of its realm. But things go awry when you discover a new civilization -- will you befriend these curious newcomers, or will you crush them and claim Sproggiwood for your own?' FROM games WHERE igdb_id = 14686 ON CONFLICT (game_id, language_code) DO NOTHING;
