INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Demon Hunter: Chronicles from Beyond', 'Demon Hunter: Chronicles from Beyond is a thrilling tale set in 1930s America. The game tells the story of Dawn Harlock, an unusual red-eyed woman, who must return to her family estate on Iowa Island to investigate the mysterious death of her mentor, Professor Ashmore. It’s not long before Dawn discovers traces of horrifying experiments and has to come face to face with an ancient evil from another world.' FROM games WHERE igdb_id = 17987 ON CONFLICT (game_id, language_code) DO NOTHING;
