INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Insanity''s Blade', 'Take a father’s journey to hell in order to save the souls of his wife and child. Insanity''s Blade: The Chronicles of Thurstan is the first in a series of games based around the journey of a sword possessed by a father''s powerful grief and hatred. This is the tale of the sword''s creation.' FROM games WHERE igdb_id = 24559 ON CONFLICT (game_id, language_code) DO NOTHING;
