INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Our Darker Purpose', 'Darker Purpose is a top-down, rogue-like action RPG that combines the ingenuity of genre-defining classics with the expansiveness and accessibility of modern day action adventure games. The gameplay is steeped in a variety of influences ranging from A Link to the Past to The Binding of Isaac to Diablo. We love games with great mechanics and awesome, bizarre storylines, and that’s what we’re creating with Our Darker Purpose.' FROM games WHERE igdb_id = 16830 ON CONFLICT (game_id, language_code) DO NOTHING;
