INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Bird Story', 'A Bird Story is a simple, surreal short about a boy and a bird with a broken wing. Its sole purpose is to tell a story, and can be viewed as a narrative/animation with interactivity -- but without a line of dialogue. It is a standalone game with its own beginning and endings; but for those who''s played To the Moon, the boy eventually grows up to become the next patient in the series.' FROM games WHERE igdb_id = 8794 ON CONFLICT (game_id, language_code) DO NOTHING;
