INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Windforge', 'WindForge is a side-scrolling block-building game where you explore hostile skies in an ever-changing Steampunk world. Everything you see can be created or destroyed, creating an RPG without barriers that rewards creative problem solving and improvisation. Take off in fully customizable airships, and embark on a journey of discovery and survival that will take you to the heart of the world and beyond.' FROM games WHERE igdb_id = 16881 ON CONFLICT (game_id, language_code) DO NOTHING;
