INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Signs of Life', 'Signs of Life is a sci-fi survival sandbox platformer with a combination of procedurally generated and hand-crafted content. You''ll explore mysterious locations, Mine blocks for resources, and meet strange (and some familiar) creatures, some of which don''t even want to kill you and eat your corpse. Along the way, you''ll be able to craft armor, weapons, gadgets and more to assist you in surviving in an inhospitable environment.' FROM games WHERE igdb_id = 16839 ON CONFLICT (game_id, language_code) DO NOTHING;
