INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Teenage Mutant Ninja Turtles: Danger of the Ooze', 'Teenage Mutant Ninja Turtles: Danger of the Ooze is a 2.5D platform video game developed by WayForward Technologies and published by Activision . It is the second video game based on the 2012 Teenage Mutant Ninja Turtles TV series and features elements from the show''s second and third seasons. It was released as a sequel to the 2013 game Teenage Mutant Ninja Turtles. The game also features gameplay elements and homages to the 1989 Teenage Mutant Ninja Turtles NES game.' FROM games WHERE igdb_id = 19092 ON CONFLICT (game_id, language_code) DO NOTHING;
