INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('elegy-for-a-dead-world', 16680, '2014-11-03', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2q1d.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arqp3.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elegy for a Dead World', 'In Elegy, you''ll travel to three worlds and write stories about their long-dead societies. You’ll lose yourself in settings inspired by the works of poets Keats, Byron, and Shelley, and use the game''s system of writing prompts to help create your own masterpieces. Explore 27 different writing challenges, through which you create narratives about the worlds you visit, from multiple perspectives. In one challenge, you play an archaeologist, uncovering clues and writing about a city''s final days; in another, you''re a thief, composing a song about searching the wreckage for valuables; and in another, you''re a bard penning a lament in rhyming couplets.' FROM games WHERE igdb_id = 16680 ON CONFLICT (game_id, language_code) DO NOTHING;
