INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Toukiden: Kiwami', '"Toukiden: Kiwami" is a hunting action game where players take on the role of a Slayer possessing unique abilities, and battle the Oni to save mankind from destruction. To defeat these huge Oni, players band together to sever, pierce, and crush parts of the Oni using the Targeted Destruction System!' FROM games WHERE igdb_id = 8657 ON CONFLICT (game_id, language_code) DO NOTHING;
