INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Qvadriga', 'Qvadriga is a tactical game of chariot racing in ancient Roman circuses, where you take control of a four horse chariot team. Choose your preferred upgrade combinations and prove your skills at the arena. Select the most cunning actions which your team could perform against the best drivers of the old world: shake reins, whip horses, choose lanes, hold tight while negotiating curves, avoid incoming attacks, block enemies path, lacerate and whip them until achieving victory.' FROM games WHERE igdb_id = 17347 ON CONFLICT (game_id, language_code) DO NOTHING;
