INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Quest for Infamy', 'Quest For Infamy is a classic point and click adventure game, in which you assume the identity of ''Mister Roehm'' a man trying to start over after running away from a shady past. Welcome to the little town of Volksville only to discover there is so much more going on in the valley than meets the eye! Come along and take a walk on the wild side with Roehm and discover just how infamous you might be.' FROM games WHERE igdb_id = 8250 ON CONFLICT (game_id, language_code) DO NOTHING;
