INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Assassin''s Creed Rogue', 'Assassin''s Creed Rogue is a 2014 action-adventure video game developed by Ubisoft Sofia and published by Ubisoft. It is the seventh major installment in the Assassin''s Creed series, and is set between 2012''s Assassin''s Creed III and 2013''s Assassin''s Creed IV: Black Flag. It also has ties to Assassin''s Creed Unity, which was released on the same day as Rogue. It is the last Assassin''s Creed game to be developed for the seventh generation of consoles, being released for PlayStation 3 and Xbox 360 in November 2014 and for Windows in March 2015.' FROM games WHERE igdb_id = 7570 ON CONFLICT (game_id, language_code) DO NOTHING;
