INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('holy-avatar-vs-maidens-of-the-dead', 10413, '2014-02-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co86cs.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar16xg.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Holy Avatar Vs Maidens of the Dead', 'Demi-god Holy Avatar and his Guild of Maidens are taking a trip to his recently bought holiday island “Holy Island“. Here he can finally relax after countless battles, but this doesn''t suit him at all, for he constantly thirsts for new adventures. After a rather rushed arrival on the beach the group make a gruesome discovery: numerous dead maidens, horribly mutilated, are scattered all over the path to the inside of the island. The Guild of Maidens is afraid that something horrible happened in the maidens’ camp on the island. Holy Avatar – secretly happy as an adventure lies ahead – is going to explore with a part of his group what exactly happened. Not knowing what kind of scale this disaster has already taken and what hazards are waiting for him and his companions inside the dense woods and caves…
