INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Twisty Planets Space Puzzle', 'Welcome to Twisty Planets - a 3D Space & Stars Puzzle Game unlike any other. Help little fella Qub escape from the twisty star planets, find stars to open portal and escape from the stars! Navigate constellations, springboards, moving platforms, teleports and reconfigurable puzzle planets to find the way out of the 3D planets. Watch out for the edges of the planets and don''t fall off! Can you find a way off the planets and into the next galaxy, constellation and stars?' FROM games WHERE igdb_id = 83577 ON CONFLICT (game_id, language_code) DO NOTHING;
