INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tony Hawk''s Shred Session', 'Tony Hawk''s Shred Session is a cancelled endless runner sports video game. A free-to-play game for iOS and Android mobile phones, it was to be the first game in the Tony Hawk''s franchise created specifically for the platform. Although the game had soft launched in a handful of territories in mid-2014 ahead of a worldwide release, in November 2014 Hawk revealed that the game was postponed indefinitely and the game was later pulled from these territories.' FROM games WHERE igdb_id = 79819 ON CONFLICT (game_id, language_code) DO NOTHING;
