INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('royal-envoy-3-collectors-edition', 132804, '2014-03-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co23n8.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Royal Envoy 3: Collector''s Edition', 'Discover new islands to develop in Royal Envoy 3 Collector''s Edition! Fish, pearls, gold and ancient pirate treasures are waiting for you to find them. Journey across 11 islands and conquer over 80 time management levels. It''s an incredible new adventure in this hit series. The CE contains 32 levels on 4 bonus islands - that''s 15 islands and 114 levels total. Get wallpapers, the soundtrack and a walkthrough. Play Royal Envoy 3 Collector''s Edition today!' FROM games WHERE igdb_id = 132804 ON CONFLICT (game_id, language_code) DO NOTHING;
