INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('grid-2-reloaded-edition', 26185, '2014-01-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8iue.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/swukqhr6kemiqdpvkmb7.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grid 2: Reloaded Edition', 'Be fast, be first and be famous in GRID 2 Reloaded, featuring the full GRID 2 game expanded with over $35 worth of additional content including two new circuits - legendary Spa and fearsome Bathurst - and 25 extra cars playable in split-screen, online and career mode. Experience aggressive racing against advanced AI and become immersed in the race with GRID 2’s new TrueFeel Handling system which powers edge of control exhilaration behind the wheel of every iconic car. The EGO Game Technology Platform delivers genre-defining visuals and jaw-dropping damage as you prove yourself across three continents in a new, evolving world of motorsport. Earn fame, fans and fortune as you blaze your way to the top in intense, relentless races on licensed circuits, beautifully realised city streets and lethal mountain roads. GRID 2 sets new standards for multiplayer racing with innovative modes, an entirely separate progression system and deep integration with RaceNet, the free online extension for Codemasters Racing games.' FROM games WHERE igdb_id = 26185 ON CONFLICT (game_id, language_code) DO NOTHING;
