INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Car Parking Game 3D - Real City Driving School', 'Car Parking Game 3D is an amazing car parking simulator game that requires highest precision! The parking situation in Car Parking Game 3D will require you to show top skills in steering, acceleration, and obstacle avoidance to get those vehicles parked in parking places. As the parking lot driver, you will drive the awesome cars around corners, obstacles, and parking lot borders with speed and accuracy.' FROM games WHERE igdb_id = 83585 ON CONFLICT (game_id, language_code) DO NOTHING;
