INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fat Princess: Piece of Cake', 'Fat Princess: Piece of Cake takes the comic medieval battle royale to the next level with a brand-new free-to-play strategic match-3 game. Charge into battle with 4 different character classes! Make matches to smash through the blue army! Collect gems to upgrade your troops! Feed cake to the princess to unleash her devastating slam attack! Trigger massive combos and save the kingdom!' FROM games WHERE igdb_id = 52212 ON CONFLICT (game_id, language_code) DO NOTHING;
