INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Surge Deluxe', 'A new energy source provides humanity with enormous electrical power, but by-product materials build up fast, and must be constantly cleared to keep pressure levels in check. Shatter the dangerous by-products by routing electrical surges between matching blocks, and then vent pressure in huge blasts to buy you more time! Surge Deluxe puts sizzling electrical energy at your fingertips!' FROM games WHERE igdb_id = 20062 ON CONFLICT (game_id, language_code) DO NOTHING;
