INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bouhou Koumakyou 2', 'Boho Koumakyou - Scarlet Family 2 is the third game of the series - preceded by Boho Bouyoumu, Reitaisai 9 - starring the cast of Touhou Koumakyou, but mainly are Remilia and Hong Meiling. Boho Koumakyou 2 is a free roaming, two dimensional platformer games with an emphasis on an exploratory action-adventure structure. Set in a massive underground maze, the map is largely contiguous, offering no breaks in play and unlocked as the player progresses through the game.' FROM games WHERE igdb_id = 204075 ON CONFLICT (game_id, language_code) DO NOTHING;
