INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Runers', 'Runers is a top-down rogue-like dungeon shooter where you explore a vast underground labyrinth and face fierce monsters and bosses. As the game advances further into the dungeon, you will gather Runes, which will be used to combine into 285 unique spells. Discovering new spells will unlock their entries in your Runedex; unlock them all! But be careful – if you die, your playthrough is finished.
