INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Steel Diver: Sub Wars', 'Dive, dive, dive for strategic subaquatic combat! This strategic first-person shooter is the successor to Steel Diver. It features more tactical action game play than typical shooters, as players are asked to navigate heavy-duty submarines while staying one step ahead of their enemies. People can compete in local four-on-four team sub battles and go online to battle submariners from around the world (as long as each person downloads the game for him- or herself).' FROM games WHERE igdb_id = 62171 ON CONFLICT (game_id, language_code) DO NOTHING;
