INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lords of the Fallen: Collector''s Edition', 'Lords of the Fallen is a challenging Action RPG set in a medieval fantasy world ruled by a Fallen God. Fighting against the formidable Lords and Generals that command his demonic army is the main feature of the game. Lords of the Fallen rewards skill and persistence among dedicated Action RPG fans. Included in this Collector''s Edition is a Handcrafted 8" Polystone Bust, Hardcover Art book, Official Soundtrack, Cloth Map, Digital Content (The Monk''s Decipher, Lion heart Park, Demonic Weapons) all packaged in a Collector''s Box.' FROM games WHERE igdb_id = 28128 ON CONFLICT (game_id, language_code) DO NOTHING;
