INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wickland', 'Wickland is an indie arena FPS game heavily inspired by classic shooters of the 90''s. Morph into several different deadly beasts to use their own unique abilities, blaze through maps at insane speed to pick up power-ups and fight your friends or foes in classic maze-like arena maps, just like the good old days. Wickland is an arena FPS dedicated to PC Gamers.' FROM games WHERE igdb_id = 9367 ON CONFLICT (game_id, language_code) DO NOTHING;
