INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'P.T.', 'P.T. (Playable Teaser) is a first-person interactive teaser directed by Hideo Kojima and developed by Kojima Productions under the alias of "7780s Studios". It is a psychological survival horror that combined simplicity with an anxiety-inducing environment. The player must investigate the gruesome backstory surrounding the house, and solve puzzles to get to the end game where a cut scene will initiate, and reveal the official teaser trailer for Silent Hills. P.T is widely accepted as a game in its own right, as not only is it considered deeply engaging, but also enjoys significant replay value thanks to its cryptic nature. Due to the cancellation on Silent Hills, it is no longer available for download.' FROM games WHERE igdb_id = 11654 ON CONFLICT (game_id, language_code) DO NOTHING;
