INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'One Upon Light', 'One Upon Light is a monochromatic styled top-down puzzle game with a photophobic protagonist. Trapped in a world of shifting shadows and light, players must manipulate objects in the environment to create a path of shadows to navigate through the levels. As the protagonist journeys through the dark, he discovers clues about his past lurking in the darkness.' FROM games WHERE igdb_id = 13551 ON CONFLICT (game_id, language_code) DO NOTHING;
