INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Donkey Kong Country: Tropical Freeze', 'All the challenging ground-pounding, barrel-blasting, side-scrolling mine cart action from the Donkey Kong Country series is back along with a bushel of new game-play elements and features. And now, there are four playable characters! Dixie Kong is back to join the adventure as a playable character alongside Diddy Kong, and for the first time in Donkey Kong Country, bearded old hero Cranky Kong joins the adventure with his bouncy cane. Any of the three can buddy up with Donkey Kong, and each character offers a different gameplay experience. On their journey to reclaim Donkey Kong Island, Donkey Kong and his friends travel across five islands with a variety of stages that include underwater areas and frozen environments.' FROM games WHERE igdb_id = 2923 ON CONFLICT (game_id, language_code) DO NOTHING;
