INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lost-civilization', 16863, '2014-03-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co21bq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar16ze.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lost Civilization', 'Race to unearth the mystery of a forgotten civilization and rescue your kidnapped fiancé in this atmospheric adventure, suitable for beginners and diehards alike, which features a haunting blend of puzzle-solving and investigation. As amateur archaeologist Sarah, journey from the dark corners of Prague to the forgotten chapters of Mayan civilization as you solve clever puzzles and unravel ancient secrets that could lead to proof that alien life exists on Earth. Featuring over 120 richly-detailed and animated scenes, haunting sound effects, and a refreshing variety of challenges ranging from point-and-click adventuring to hidden object challenges, the fate of the world rests in your hands.' FROM games WHERE igdb_id = 16863 ON CONFLICT (game_id, language_code) DO NOTHING;
