INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heroes of a Broken Land', 'Heroes of a Broken Land is a turn-based, dungeon crawling, town management RPG. Explore procedurally generated worlds and dungeons with multiple parties of heroes. Ally with other towns to recruit new and more powerful heroes. Explore and loot countless dungeons on your quest to save the world.' FROM games WHERE igdb_id = 17663 ON CONFLICT (game_id, language_code) DO NOTHING;
