INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Among the Sleep', 'Among the Sleep is a first person horror adventure, in which you play a two year old child. After waking up in the middle of the night to mysterious sounds, you start exploring the dark looking for comfort. The game explores horror through atmosphere and exploration, not with scores and combat systems. In Among the Sleep you’re vulnerable, scared, and trying to make sense of the world' FROM games WHERE igdb_id = 7642 ON CONFLICT (game_id, language_code) DO NOTHING;
